SELECT t.id, t.school_id, s.school_name AS school_name, NULL AS user_id, NULL AS username, t.teacher_code AS job_number, t.teacher_name AS name, t.gender, t.phone, t.email, NULL AS id_card, t.subject, t.title, NULL AS entry_date, t.status, '' AS remark, t.create_time FROM teacher t LEFT JOIN school s ON t.school_id = s.id WHERE t.deleted = 0
AND t.school_id = #{query.schoolId}
AND t.teacher_code = #{query.jobNumber}
AND t.teacher_name LIKE CONCAT('%', #{query.name}, '%')
AND t.phone = #{query.phone}
AND t.subject LIKE CONCAT('%', #{query.subject}, '%')
AND t.status = #{query.status}
ORDER BY t.create_time DESC

SELECT id, school_id, teacher_name AS name, teacher_code AS job_number, subject, '' AS remark FROM teacher WHERE school_id = #{schoolId} AND deleted = 0
AND status = #{status}
ORDER BY teacher_name ASC
